SELECT *
FROM app_rag_requests
WHERE user_id=#{userId,jdbcType=BIGINT}
AND request_key=#{requestKey,jdbcType=VARCHAR}
FOR UPDATE

SELECT id
FROM rag_sessions
WHERE id=#{sessionId,jdbcType=BIGINT}
AND user_id=#{userId,jdbcType=BIGINT}
AND target_scope->>'deletedAt' IS NULL
FOR SHARE

mapper.update:
UPDATE rag_queries
SET workflow_state=CASE WHEN EXISTS(SELECT 1
FROM app_rag_requests
WHERE id=#{requestId,jdbcType=OTHER}
AND state='cancelled') THEN 'cancelled' ELSE 'failed' END,error_code=#{errorCode,jdbcType=VARCHAR},completed_at=now()
WHERE id=#{queryId,jdbcType=BIGINT}

mapper.select:
SELECT target_scope::text
FROM rag_sessions
WHERE id=#{sessionId,jdbcType=BIGINT}
AND user_id=#{userId,jdbcType=BIGINT}

SELECT major,grade,target_cohort
FROM student_profiles
WHERE user_id=#{userId,jdbcType=BIGINT}

SELECT r.id,r.request_key,r.state,r.error_code,r.session_id,r.query_id,r.response,r.created_at,r.updated_at
FROM app_rag_requests r
LEFT JOIN rag_sessions s ON s.id=r.session_id
WHERE r.user_id=#{userId,jdbcType=BIGINT}
AND r.request_key=#{requestKey,jdbcType=VARCHAR}
AND (r.session_id IS NULL OR s.target_scope->>'deletedAt' IS NULL)

mapper.update:
UPDATE app_rag_requests
SET lease_until=now()+interval '2 minutes'
WHERE id=#{id,jdbcType=OTHER}
AND state='running'
AND instance_id=#{instanceId,jdbcType=OTHER}
